from _lib import *
lesson("modals-past-deduction", "Czasowniki modalne", "Dedukcja i krytyka w przeszłości: must have, can't have, should have", 7,
 "Modal + have + past participle pozwala mówić o przeszłości z różnym stopniem pewności lub oceniać przeszłe działania. must have done – jestem pewien, że tak było; can't/couldn't have done – jestem pewien, że tak nie było; may/might/could have done – możliwe, że tak było; should have / ought to have done – krytyka lub żal (powinien był, ale nie zrobił); needn't have done – zrobił, choć nie musiał.",
 "To jedna z najczęściej sprawdzanych struktur w Part 4 i Speaking (spekulowanie o zdjęciach i sytuacjach). Pozwala precyzyjnie wyrazić pewność, wątpliwość i krytykę.",
 dict(scheme="podmiot + must/can't/might/could/should/needn't + have + past participle", word_order="She must have forgotten. / He can't have seen us. / You should have told me.",
      affirmative=["They must have left early.", "She might have missed the bus.", "You should have called."],
      negative=["He can't have known about it.", "She might not have received my message.", "You shouldn't have shouted at him."],
      questions=["Could he have taken the wrong train?", "Should I have told her the truth?"]),
 [X("The streets are wet – it must have rained.", "Ulice są mokre – musiało padać.", "Mocna dedukcja z dowodu."),
  X("She can't have finished already – she only started ten minutes ago.", "Niemożliwe, żeby już skończyła – zaczęła dziesięć minut temu.", "Negatywna pewność → can't have (nie: mustn't have)."),
  X("He might have forgotten about the meeting.", "Może zapomniał o spotkaniu.", "Możliwość."),
  X("They could have taken a taxi, but they walked.", "Mogli wziąć taksówkę, ale poszli pieszo.", "Could have – niewykorzystana możliwość."),
  X("You should have told me you were vegetarian.", "Powinieneś był mi powiedzieć, że jesteś wegetarianinem.", "Krytyka przeszłego działania."),
  X("I shouldn't have eaten so much.", "Nie powinienem był tyle jeść.", "Żal."),
  X("You needn't have brought a present.", "Niepotrzebnie przynosiłeś prezent.", "Zrobiłeś, choć nie było trzeba."),
  X("We didn't need to queue because we had tickets.", "Nie musieliśmy stać w kolejce, bo mieliśmy bilety.", "Nie trzeba było i nie zrobiliśmy → didn't need to."),
  X("She must have been sleeping when I called.", "Musiała spać, kiedy dzwoniłem.", "Forma ciągła: must have been + -ing."),
  X("The letter may have been lost in the post.", "List mógł zaginąć na poczcie.", "Strona bierna: may have been + past participle."),
  X("He ought to have apologised.", "Powinien był przeprosić.", "Ought to have = should have (bardziej formalnie).")],
 [C("can't have vs mustn't have", "Dla negatywnej dedukcji używamy can't/couldn't have. Mustn't have nie jest używane w tym znaczeniu.", "He can't have seen it (na pewno nie widział)."),
  C("needn't have done vs didn't need to do", "Needn't have – zrobiłeś niepotrzebnie. Didn't need to – zwykle nie zrobiłeś, bo nie było trzeba.", "I needn't have hurried (pospieszyłem się na próżno)."),
  C("could have vs might have", "Obie oznaczają możliwość; could have dodatkowo – niewykorzystana szansa.", "You could have died! (było blisko).")],
 [W("He mustn't have heard me.", "He can't have heard me.", "Negatywna dedukcja → can't have."),
  W("She must has gone.", "She must have gone.", "Po modalnym zawsze have (nie has)."),
  W("You should have came earlier.", "You should have come earlier.", "Past participle: come."),
  W("I should of called you.", "I should have called you.", "'Of' to błąd wynikający z wymowy 'should've'.")],
 ["Was/were to have done oznacza plan, który się nie spełnił: The bridge was to have opened in May.",
  "Would have done bez if – wyobrażenie: I would have liked to see it.",
  "W pytaniach o dedukcję używamy could, nie must: Could she have left?"],
 [dict(en="The ancient builders must have possessed remarkable engineering skills.", pl="Starożytni budowniczowie musieli mieć niezwykłe umiejętności inżynieryjne.", note="Dedukcja w tekście akademickim."),
  dict(en="The authorities could have prevented the disaster had they acted sooner.", pl="Władze mogły zapobiec katastrofie, gdyby zareagowały wcześniej.", note="Połączenie z inwersją warunkową."),
  dict(en="In hindsight, the company ought to have diversified much earlier.", pl="Z perspektywy czasu firma powinna była zdywersyfikować działalność dużo wcześniej.", note="In hindsight + ought to have.")],
 [G("The lights are off. They ___ (must / go) to bed.", ["must have gone"], "Pewna dedukcja."),
  G("He ___ (can't / write) this – he doesn't speak French.", ["can't have written", "cannot have written", "couldn't have written"], "Negatywna pewność."),
  G("You ___ (should / ask) for help instead of struggling alone.", ["should have asked"], "Krytyka."),
  M("I ___ cooked so much – nobody was hungry.", ["needn't have", "didn't need to", "mustn't have", "can't have"], "needn't have", "Zrobiłem niepotrzebnie.", {"didn't need to": "Wymagałoby formy podstawowej: didn't need to cook.", "mustn't have": "Nie wyraża braku konieczności.", "can't have": "To dedukcja, nie ocena."}),
  G("She ___ (might / not / receive) my email yet.", ["might not have received", "may not have received"], "Możliwość z przeczeniem."),
  K("I'm sure he forgot his keys.", "MUST", "He ___ keys.", ["must have forgotten his"], "Pewność → must have."),
  K("It was a mistake to sell the car.", "SHOULDN'T", "We ___ the car.", ["shouldn't have sold", "should not have sold"], "Żal → shouldn't have."),
  E("She mustn't have seen us – she didn't wave.", ["She can't have seen us – she didn't wave.", "She can't have seen us", "She couldn't have seen us"], "Negatywna dedukcja → can't have.")],
 [K("Perhaps the parcel was delivered to the wrong address.", "MAY", "The parcel ___ to the wrong address.", ["may have been delivered"], "Bierna: may have been delivered."),
  K("It is impossible that she saw the film – it isn't out yet.", "CAN'T", "She ___ the film – it isn't out yet.", ["can't have seen", "cannot have seen"], "can't have seen."),
  K("It wasn't necessary for you to wait, but you did.", "NEEDN'T", "You ___ for me.", ["needn't have waited", "need not have waited"], "needn't have waited."),
  G("I'm sure they ___ (must / work) all night – they look exhausted.", ["must have been working"], "Ciągła dedukcja."),
  M("You ___ me! I'd have helped.", ["should have told", "must have told", "can't have told", "needn't have told"], "should have told", "Wyrzut.", {"must have told": "To dedukcja, nie wyrzut.", "can't have told": "Dedukcja negatywna – zły sens.", "needn't have told": "Oznaczałoby, że powiedziałeś niepotrzebnie."}),
  T("Musiałeś być bardzo zmęczony.", ["You must have been very tired.", "You must have been really tired."], "must have been.")])
